package io.fireflysoftware.common.config.core.authority;
import io.fireflysoftware.common.config.core.authority.impl.TenantResourceBindingNativeAuthorityImpl;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingContracts.*;
import io.fireflysoftware.common.config.models.repositories.tenantbinding.TenantResourceBindingNativeRepository;
import com.fasterxml.jackson.databind.json.JsonMapper;
import org.junit.jupiter.api.Test;
import org.springframework.data.r2dbc.core.R2dbcEntityTemplate;
import org.springframework.r2dbc.connection.R2dbcTransactionManager;
import org.springframework.transaction.reactive.TransactionalOperator;
import reactor.core.publisher.Mono;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class TenantResourceBindingNativeAdapterTest {
 @Test void outsideTheActualOwningTransactionNativeRepositoryIsNeverCalled(){var f=new TenantResourceBindingServiceTest.Fixture();var repository=mock(TenantResourceBindingNativeRepository.class);var template=mock(R2dbcEntityTemplate.class);var client=mock(org.springframework.r2dbc.core.DatabaseClient.class);when(template.getDatabaseClient()).thenReturn(client);when(client.getConnectionFactory()).thenReturn(f.factory);var adapter=new TenantResourceBindingNativeAuthorityImpl(template,repository);var admission=f.lookup.authorize(f.budget()).block();assertThrows(Exception.class,()->adapter.openLookup(admission).block());verifyNoInteractions(repository);}
 @Test void exactOpaqueIdentityAndSameOriginalDeadlineReachRealNativeQuery()throws Exception{var f=new TenantResourceBindingServiceTest.Fixture();var repository=mock(TenantResourceBindingNativeRepository.class);var template=mock(R2dbcEntityTemplate.class);var client=mock(org.springframework.r2dbc.core.DatabaseClient.class);when(template.getDatabaseClient()).thenReturn(client);when(client.getConnectionFactory()).thenReturn(f.factory);var adapter=new TenantResourceBindingNativeAuthorityImpl(template,repository);var admission=f.lookup.authorize(f.budget()).block();when(repository.openLookup(anyString(),anyString(),anyString(),anyLong())).thenReturn(Mono.just(JsonMapper.builder().build().writeValueAsString(f.window(1,State.ACTIVE,500))));var result=TransactionalOperator.create(new R2dbcTransactionManager(f.factory)).transactional(adapter.openLookup(admission)).block();assertEquals(TenantResourceBindingServiceTest.NS.platformTenant(),admission.namespace().platformTenant());verify(repository).openLookup(eq(admission.namespace().issuer()),eq("actual-subject"),eq(admission.namespace().platformTenant()),eq(admission.validUntilEpochMillis()));assertEquals(State.ACTIVE,result.state());assertEquals(1,f.begins.get());assertEquals(1,f.commits.get());}
 @Test void missingNativeFunctionResultRefusesAndRollsBack(){var f=new TenantResourceBindingServiceTest.Fixture();var repository=mock(TenantResourceBindingNativeRepository.class);var template=mock(R2dbcEntityTemplate.class);var client=mock(org.springframework.r2dbc.core.DatabaseClient.class);when(template.getDatabaseClient()).thenReturn(client);when(client.getConnectionFactory()).thenReturn(f.factory);var adapter=new TenantResourceBindingNativeAuthorityImpl(template,repository);when(repository.openLookup(anyString(),anyString(),anyString(),anyLong())).thenReturn(Mono.empty());var admission=f.lookup.authorize(f.budget()).block();assertThrows(Exception.class,()->TransactionalOperator.create(new R2dbcTransactionManager(f.factory)).transactional(adapter.openLookup(admission)).block());assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}
 @Test void delayedSubscriptionDoesNotRetainAnEarlierLongerNativeQueryTimeout(){var f=new TenantResourceBindingServiceTest.Fixture();var repository=mock(TenantResourceBindingNativeRepository.class);var template=mock(R2dbcEntityTemplate.class);var client=mock(org.springframework.r2dbc.core.DatabaseClient.class);when(template.getDatabaseClient()).thenReturn(client);when(client.getConnectionFactory()).thenReturn(f.factory);var adapter=new TenantResourceBindingNativeAuthorityImpl(template,repository);when(repository.openLookup(anyString(),anyString(),anyString(),anyLong())).thenReturn(Mono.never());var admission=f.lookup.authorize(f.budget()).block();reactor.test.StepVerifier.withVirtualTime(()->{var call=adapter.openLookup(admission);f.time.advance(790);return TransactionalOperator.create(new R2dbcTransactionManager(f.factory)).transactional(call);}).thenAwait(java.time.Duration.ofMillis(20)).expectError(java.util.concurrent.TimeoutException.class).verify(java.time.Duration.ofMillis(300));assertEquals(0,f.commits.get());assertEquals(1,f.rollbacks.get());}

 @Test void unrelatedPhysicalFactoryCannotAcquireNativeAuthority(){var owner=new TenantResourceBindingServiceTest.Fixture();var unrelated=new TenantResourceBindingServiceTest.Fixture();var repository=mock(TenantResourceBindingNativeRepository.class);var template=mock(R2dbcEntityTemplate.class);var client=mock(org.springframework.r2dbc.core.DatabaseClient.class);when(template.getDatabaseClient()).thenReturn(client);when(client.getConnectionFactory()).thenReturn(owner.factory);var adapter=new TenantResourceBindingNativeAuthorityImpl(template,repository);var admission=owner.lookup.authorize(owner.budget()).block();assertThrows(Exception.class,()->TransactionalOperator.create(new R2dbcTransactionManager(unrelated.factory)).transactional(adapter.openLookup(admission)).block());verifyNoInteractions(repository);assertEquals(0,owner.begins.get());assertEquals(1,unrelated.rollbacks.get());}

}
